class Solution {
    long long gcdll(long long a, long long b) {
        while (b) {
            long long t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
public:
    vector<int> replaceNonCoprimes(vector<int>& nums) {
        vector<int> st;
        st.reserve(nums.size());
        for (int x : nums) {
            st.push_back(x);
            while (st.size() >= 2) {
                long long a = st[st.size() - 2];
                long long b = st[st.size() - 1];
                long long g = gcdll(a, b);
                if (g > 1) {
                    st.pop_back();
                    st.pop_back();
                    long long l = a / g * b;
                    st.push_back((int)l);
                } else {
                    break;
                }
            }
        }
        return st;
    }
};
